def calculate_fee(amount):
    rate = 0.02 if amount < 5000 else 0.015
    return round(amount * rate, 2)


def validate(amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    return True


def refund(amount, fee):
    return max(amount - fee, 0)
